#include <iostream>
#include <iomanip>

int main() {
    int suma = 15 + 7;
    std::cout << suma << "\n";

    int cociente = 10 / 3;
    std::cout << cociente << "\n";

    int resto = 10 % 3;
    std::cout << resto << "\n";

    double real = (double)10 / 3;
    std::cout << std::fixed << std::setprecision(2) << real << "\n";

    return 0;
}
